DO $$
BEGIN

    UPDATE refund_requests
    SET processing_status = 'expedited'
    WHERE order_total >= 500;

    UPDATE refund_requests
    SET priority_flag = TRUE
    WHERE return_reason = 'defective';

    UPDATE refund_requests
    SET refund_amount = order_total * 1.10
    WHERE processing_status = 'expedited' AND priority_flag = TRUE;

    UPDATE refund_requests
    SET refund_amount = order_total * 1.00
    WHERE priority_flag = TRUE AND refund_amount IS NULL;

END $$;


SELECT * FROM refund_requests ORDER BY request_id;
